import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"伤时","description":"","frontmatter":{"title":"伤时","date":"2026-11-24T00:00:00.000Z","seq":63,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"悼乱","link":"/blogs/楚辞/悼乱.html"},"next":{"text":"哀岁","link":"/blogs/楚辞/哀岁.html"}},"headers":[],"relativePath":"blogs/楚辞/伤时.md","filePath":"blogs/楚辞/伤时.md"}'),o={name:"blogs/楚辞/伤时.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="伤时" tabindex="-1">伤时 <a class="header-anchor" href="#伤时" aria-label="Permalink to &quot;伤时&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">惟昊天兮昭灵，阳气发兮清明。</p><p class="poem-stanza">风習習兮和暖，百草萌兮华荣。</p><p class="poem-stanza">堇荼茂兮扶疏，蘅芷彫兮莹嫇。</p><p class="poem-stanza">愍贞良兮遇害，将夭折兮碎糜。</p><p class="poem-stanza">时混混兮浇饡，哀当世兮莫知。</p><p class="poem-stanza">览往昔兮俊彦，亦诎辱兮系纍。</p><p class="poem-stanza">管束缚兮桎梏，百贸易兮传卖。</p><p class="poem-stanza">遭桓缪兮识举，才德用兮列施。</p><p class="poem-stanza">且从容兮自慰，玩琴书兮游戏。</p><p class="poem-stanza">迫中国兮迮陿，吾欲之兮九夷。</p><p class="poem-stanza">超五岭兮嵯峨，观浮石兮崔嵬。</p><p class="poem-stanza">陟丹山兮炎野，屯余车兮黄支。</p><p class="poem-stanza">就祝融兮稽疑，嘉己行兮无为。</p><p class="poem-stanza">乃回朅兮北逝，遇神孈兮宴娭。</p><p class="poem-stanza">欲静居兮自娱，心愁慼兮不能。</p><p class="poem-stanza">放余辔兮策驷，忽飙腾兮浮云。</p><p class="poem-stanza">蹠飞杭兮越海，从安期兮蓬莱。</p><p class="poem-stanza">缘天梯兮北上，登太一兮玉台。</p><p class="poem-stanza">使素女兮鼓簧，乘戈和兮讴谣。</p><p class="poem-stanza">声噭誂兮清和，音晏衍兮要婬。</p><p class="poem-stanza">咸欣欣兮酣乐，余眷眷兮独悲。</p><p class="poem-stanza">顾章华兮太息，志恋恋兮依依。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
